#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int khong_khop = 0;
    for (int i = 0; i < n; i++) {
        int mong, thuc;
        scanf("%d %d", &mong, &thuc);
        if (mong != thuc) khong_khop++;
    }
    printf("%d\n", khong_khop);
    return 0;
}
